insert into public.iterations (id, project_id, step_number, ai_tool, prompt, raw_answer, critique, import_source, source_url, source_conversation_id, source_step_id, imported_at, student_marked_ai_error, ai_error_evidence, created_at) values
  ('50000000-0000-0000-0002-000000000001', '40000000-0000-0000-0000-000000000002', 1, 'ChatGPT', 'Outline an essay arguing why universities split assessment into two lanes.', '1. Generative AI can now write fluent essays. 2. Lane 1 keeps secure, supervised assessment. 3. Lane 2 allows open AI use and marks the process. 4. Graders need visible evidence of student thinking. 5. Staff workload is a separate issue.', 'Kept 1 and 3. Workload is off-topic.', 'public_link', 'https://chatgpt.com/share/a1b2c3d4-john-essay-2', 'a1b2c3d4-john-essay-2', 'turn-1', '2026-10-05 10:10+11', false, null, '2026-10-05 10:02+11'),
  ('50000000-0000-0000-0002-000000000002', '40000000-0000-0000-0000-000000000002', 2, 'ChatGPT', 'Give me two academic sources on assessment redesign for generative AI.', 'Two sources: Smith and Lee (2022), Rethinking Assessment After Generative AI, Journal of Higher Education Design; and the University of Sydney two-lane assessment guidance on its teaching website.', 'Smith and Lee does not exist. I searched Google Scholar and the library, then replaced it with the Sydney guidance.', 'public_link', 'https://chatgpt.com/share/a1b2c3d4-john-essay-2', 'a1b2c3d4-john-essay-2', 'turn-2', '2026-10-05 10:10+11', true, 'No record of Smith and Lee (2022) in Google Scholar or the library catalogue.', '2026-10-05 10:05+11'),
  ('50000000-0000-0000-0002-000000000003', '40000000-0000-0000-0000-000000000002', 3, 'ChatGPT', 'Draft a three-sentence introduction for the essay.', 'Generative AI now writes fluent essays in seconds, so universities can no longer rely on take-home tasks alone to prove what a student knows. The two-lane model separates secure, supervised assessment in Lane 1 from open tasks in Lane 2 where students may use AI. This essay argues that the second lane only works when graders can see how students used the tools.', 'Too generic. Rewrote it in my own words.', 'public_link', 'https://chatgpt.com/share/a1b2c3d4-john-essay-2', 'a1b2c3d4-john-essay-2', 'turn-3', '2026-10-06 15:30+11', false, null, '2026-10-06 15:20+11'),
  ('50000000-0000-0000-0002-000000000004', '40000000-0000-0000-0000-000000000002', 4, 'ChatGPT', 'Why do universities split assessment into two lanes, and when was the model introduced?', 'The two-lane model, introduced in 2019, separates secure assessment from open tasks where AI use is allowed. Lane 1 restricts AI; Lane 2 lets students use it.', 'Wrong date. Sydney introduced it in 2023. I checked their article and fixed my intro.', 'public_link', 'https://chatgpt.com/share/a1b2c3d4-john-essay-2', 'a1b2c3d4-john-essay-2', 'turn-4', '2026-10-06 15:30+11', true, 'The University of Sydney article dates the two-lane model to 2023, not 2019.', '2026-10-06 15:24+11'),
  ('50000000-0000-0000-0002-000000000005', '40000000-0000-0000-0000-000000000002', 5, 'Claude', 'Strengthen this paragraph: most students use AI every week and staff find chat logs too long to read.', 'Most students already use AI tools every week, and staff say that raw chat logs are too long to read across a large cohort. A structured log changes that: every prompt, answer and critique becomes a step, so a grader can audit the process in minutes rather than hours.', 'Clear, so I kept it. Timed myself reading three logs: about ten minutes each, so rather than hours is fair.', 'pasted_text', null, null, null, '2026-10-07 09:45+11', false, null, '2026-10-07 09:40+11'),
  ('50000000-0000-0000-0002-000000000006', '40000000-0000-0000-0000-000000000002', 6, 'Claude', 'Is my conclusion consistent with the evidence in my essay?', 'Mostly, but paragraph 4 overstates the survey results. Consider softening that claim before you submit.', 'Looks good.', 'pasted_text', null, null, null, '2026-10-08 18:12+11', false, null, '2026-10-08 18:10+11'),
  ('50000000-0000-0000-0002-000000000007', '40000000-0000-0000-0000-000000000002', 7, 'ChatGPT', 'Check this statistic for me: what share of students use AI tools every week?', 'According to the survey, 92 percent of students use AI tools every week.', 'The survey table says 71 percent. The AI misquoted it, so I corrected the figure.', 'pasted_text', null, null, null, '2026-10-09 08:35+11', true, 'Table 2 of the survey reports 71 percent weekly use, not 92 percent.', '2026-10-09 08:30+11'),
  ('50000000-0000-0000-0002-000000000008', '40000000-0000-0000-0000-000000000002', 8, 'ChatGPT', 'Tighten the wording of my second last paragraph.', 'Graders do not need to read every chat in full. A structured log lets them see which answers were challenged, which were checked and which were changed, so they can spend their time on the steps that matter most.', 'The revised wording enhances clarity and conciseness while preserving the original meaning, making the argument more compelling and accessible to readers.', 'pasted_text', null, null, null, '2026-10-09 19:08+11', false, null, '2026-10-09 19:05+11'),
  ('50000000-0000-0000-0002-000000000009', '40000000-0000-0000-0000-000000000002', 9, 'ChatGPT', 'Proofread the whole essay and fix typos.', 'Graders do not need to read every chat in full. A structured log lets them see which answers were challenged, which were checked and which were changed, so they can spend their time on the steps that matter most. Marking the process rewards students who question the tool.', 'Fixed two typos it found. Ignored its suggested rewrite of my conclusion.', 'pasted_text', null, null, null, '2026-10-10 08:55+11', false, null, '2026-10-10 08:50+11'),
  ('50000000-0000-0000-0001-000000000001', '40000000-0000-0000-0000-000000000001', 1, 'ChatGPT', 'Outline an essay arguing why universities split assessment into two lanes.', '1. Generative AI can now write fluent essays. 2. Lane 1 keeps secure, supervised assessment. 3. Lane 2 allows open AI use and marks the process. 4. Graders need visible evidence of student thinking. 5. Staff workload is a separate issue.', 'Kept 1 and 3. Workload is off-topic.', 'manual', null, null, null, null, false, null, '2026-10-10 10:02+11'),
  ('50000000-0000-0000-0001-000000000002', '40000000-0000-0000-0000-000000000001', 2, 'ChatGPT', 'Give me two academic sources on assessment redesign for generative AI.', 'Two sources: Smith and Lee (2022), Rethinking Assessment After Generative AI, Journal of Higher Education Design; and the University of Sydney two-lane assessment guidance on its teaching website.', 'Smith and Lee does not exist. I searched Google Scholar and the library, then replaced it with the Sydney guidance.', 'manual', null, null, null, null, true, 'No record of Smith and Lee (2022) in Google Scholar or the library catalogue.', '2026-10-10 10:05+11'),
  ('50000000-0000-0000-0001-000000000003', '40000000-0000-0000-0000-000000000001', 3, 'ChatGPT', 'Draft a three-sentence introduction for the essay.', 'Generative AI now writes fluent essays in seconds, so universities can no longer rely on take-home tasks alone to prove what a student knows. The two-lane model separates secure, supervised assessment in Lane 1 from open tasks in Lane 2 where students may use AI. This essay argues that the second lane only works when graders can see how students used the tools.', 'Too generic. Rewrote it in my own words.', 'manual', null, null, null, null, false, null, '2026-10-11 15:20+11'),
  ('50000000-0000-0000-0001-000000000004', '40000000-0000-0000-0000-000000000001', 4, 'ChatGPT', 'Why do universities split assessment into two lanes, and when was the model introduced?', 'The two-lane model, introduced in 2019, separates secure assessment from open tasks where AI use is allowed. Lane 1 restricts AI; Lane 2 lets students use it.', null, 'public_link', 'https://chatgpt.com/share/6f2a91c4-essay-2', '6f2a91c4-essay-2', 'turn-1', '2026-10-12 14:20+11', true, 'The University of Sydney article dates the two-lane model to 2023, not 2019.', '2026-10-12 14:19+11'),
  ('50000000-0000-0000-0001-000000000005', '40000000-0000-0000-0000-000000000001', 5, 'ChatGPT', 'Strengthen this paragraph: most students use AI every week and staff find chat logs too long to read.', 'Most students already use AI tools every week, and staff say that raw chat logs are too long to read across a large cohort. A structured log changes that: every prompt, answer and critique becomes a step, so a grader can audit the process in minutes rather than hours.', null, 'public_link', 'https://chatgpt.com/share/6f2a91c4-essay-2', '6f2a91c4-essay-2', 'turn-2', '2026-10-12 14:20+11', false, null, '2026-10-12 14:19+11'),
  ('50000000-0000-0000-0003-000000000001', '40000000-0000-0000-0000-000000000003', 1, 'ChatGPT', 'Explain why universities keep supervised exams.', 'Supervised exams give universities direct evidence of what a student can do without help. They also protect the value of the degree for employers who rely on it.', 'Good points. Checked them against the Lane 1 policy page.', 'manual', null, null, null, null, false, null, '2026-10-07 11:00+11'),
  ('50000000-0000-0000-0003-000000000002', '40000000-0000-0000-0000-000000000003', 2, 'ChatGPT', 'Explain what Lane 2 is for.', 'Lane 2 lets students use AI openly because graduates will use it at work. Marking the process, not just the product, rewards students who question the tool.', 'Accurate. The assessment policy says the same.', 'manual', null, null, null, null, false, null, '2026-10-07 11:06+11'),
  ('50000000-0000-0000-0003-000000000003', '40000000-0000-0000-0000-000000000003', 3, 'ChatGPT', 'Combine these into one paragraph.', 'Supervised exams give universities direct evidence of what a student can do without help. Lane 2 lets students use AI openly because graduates will use it at work.', 'Reads well, matches my notes.', 'manual', null, null, null, null, false, null, '2026-10-08 14:30+11'),
  ('50000000-0000-0000-0003-000000000004', '40000000-0000-0000-0000-000000000003', 4, 'ChatGPT', 'Suggest a closing sentence.', 'Together the two lanes let a degree certify both independent knowledge and sensible use of AI.', 'Too long, so I cut it to one line.', 'manual', null, null, null, null, false, null, '2026-10-09 10:15+11'),
  ('50000000-0000-0000-0004-000000000001', '40000000-0000-0000-0000-000000000004', 1, 'ChatGPT', 'Summarise the two-lane model in two sentences.', 'The two-lane model splits assessment into secure tasks where AI is restricted and open tasks where AI is allowed. It aims to protect the integrity of degrees while preparing students to work with AI.', 'Accurate. Matches the Sydney page I read, so I kept the second sentence.', 'manual', null, null, null, null, false, null, '2026-10-08 09:00+11'),
  ('50000000-0000-0000-0004-000000000002', '40000000-0000-0000-0000-000000000004', 2, 'ChatGPT', 'When was the model introduced?', 'The model was introduced in 2019 and has been refined every year since.', 'Wrong year, it was 2023. Checked the article and fixed my notes.', 'manual', null, null, null, null, true, 'Sydney''s announcement of the two-lane model is dated 2023.', '2026-10-08 09:04+11'),
  ('50000000-0000-0000-0004-000000000003', '40000000-0000-0000-0000-000000000004', 3, 'ChatGPT', 'Suggest a title for the essay.', 'Two Lanes, One Degree: Assessing Learning in the Age of AI', 'Too clever, so I wrote my own title.', 'manual', null, null, null, null, false, null, '2026-10-08 09:10+11'),
  ('50000000-0000-0000-0005-000000000001', '40000000-0000-0000-0000-000000000005', 1, 'ChatGPT', 'Write a paragraph on why Lane 1 exists.', 'Lane 1 exists to give universities secure evidence of what students can do alone. Supervised tasks protect the value of the degree, and they reassure employers that graduates meet the standard.', 'Fine.', 'manual', null, null, null, null, false, null, '2026-10-10 12:00+11'),
  ('50000000-0000-0000-0005-000000000002', '40000000-0000-0000-0000-000000000005', 2, 'ChatGPT', 'Same again, please.', 'Lane 1 exists to give universities secure evidence of what students can do alone. Supervised tasks protect the value of the degree, and they reassure employers that graduates meet the standard.', 'Same.', 'manual', null, null, null, null, false, null, '2026-10-10 12:03+11'),
  ('50000000-0000-0000-0006-000000000001', '40000000-0000-0000-0000-000000000006', 1, 'ChatGPT', 'List three risks of marking AI-assisted work.', 'Risks include unequal access to AI tools, graders rewarding polish over thinking, and students hiding how they used the tool.', 'The second one is the real risk. I will argue it in my essay.', 'manual', null, null, null, null, false, null, '2026-10-11 19:00+11'),
  ('50000000-0000-0000-0006-000000000002', '40000000-0000-0000-0000-000000000006', 2, 'ChatGPT', 'Give a counter-argument to my claim.', 'A critic could say that a log can be faked, so it proves little about real effort.', 'Fair point. I answered it by saying the log is evidence for discussion, not proof.', 'manual', null, null, null, null, false, null, '2026-10-11 19:10+11'),
  ('50000000-0000-0000-0008-000000000001', '40000000-0000-0000-0000-000000000008', 1, 'ChatGPT', 'What is the difference between a primary key and a foreign key?', 'A primary key uniquely identifies each row in a table. A foreign key is a column that refers to the primary key of another table and keeps the two tables consistent.', 'Correct. Matches my lecture notes.', 'manual', null, null, null, null, false, null, '2026-10-09 10:00+11'),
  ('50000000-0000-0000-0008-000000000002', '40000000-0000-0000-0000-000000000008', 2, 'ChatGPT', 'Give an example where a foreign key is optional.', 'A student table can have an optional supervisor_id that is null when no supervisor is assigned.', 'Good, null means no supervisor. I used the idea in my reflection.', 'manual', null, null, null, null, false, null, '2026-10-09 10:08+11'),
  ('50000000-0000-0000-0008-000000000003', '40000000-0000-0000-0000-000000000008', 3, 'ChatGPT', 'Can a table have two primary keys?', 'Yes, a table can have two primary keys as long as they are on different columns.', 'Wrong. A table has one primary key, which may span several columns. I checked the PostgreSQL docs.', 'manual', null, null, null, null, true, 'The PostgreSQL documentation says a table can have at most one primary key.', '2026-10-09 10:15+11')
insert into public.final_versions (id, project_id, version_number, extracted_text, original_filename, is_current, submitted_at, created_at) values
  ('60000000-0000-0000-0002-000000000001', '40000000-0000-0000-0000-000000000002', 1, E'Generative AI now writes fluent essays in seconds, so universities can no longer out-design it. Sydney introduced the two-lane model in 2023. Lane 1 is supervised and secure, while Lane 2 lets students use AI openly and marks how they use it. This essay argues that Lane 2 only works if graders can see the thinking behind the work. A student who catches a source the AI invented is doing exactly the evaluation the model was designed to reward.\n\nMost students already use AI tools every week, and staff say that raw chat logs are too long to read across a large cohort. A structured log changes that: every prompt, answer and critique becomes a step, so a grader can audit the process in minutes rather than hours.\n\nI tested this on my own work. In Essay 2 I caught three errors: a source that does not exist, a wrong date and a misquoted survey figure. The survey reports 71 percent weekly use, not the 92 percent the AI gave me. Each one only surfaced because I stopped to check the answer.\n\nGraders do not need to read every chat in full. A structured log lets them see which answers were challenged, which were checked and which were changed, so they can spend their time on the steps that matter most. Marking the process rewards students who question the tool. That is a fairer reward than marking polished text alone.', 'essay2-final.docx', true, '2026-10-10 09:12+11', '2026-10-10 09:12+11'),
  ('60000000-0000-0000-0003-000000000001', '40000000-0000-0000-0000-000000000003', 1, E'Supervised exams give universities direct evidence of what a student can do without help. Lane 2 lets students use AI openly because graduates will use it at work.\n\nIn my own experience, the exam lane is where I find out what I really remember, and the open lane is where I learn how to question a confident answer. Together the lanes certify both knowledge and sensible AI use.', 'alex-kim-essay-2.docx', true, '2026-10-09 16:40+11', '2026-10-09 16:40+11'),
  ('60000000-0000-0000-0004-000000000001', '40000000-0000-0000-0000-000000000004', 1, E'The two-lane model was introduced at Sydney in 2023. It aims to protect the integrity of degrees while preparing students to work with AI. I used the AI to summarise the idea, then checked the date myself, because it gave me the wrong year.\n\nWhat I learned is that a confident answer is not a checked answer.', 'jane-roe-essay-2.docx', true, '2026-10-09 11:05+11', '2026-10-09 11:05+11'),
  ('60000000-0000-0000-0005-000000000001', '40000000-0000-0000-0000-000000000005', 1, E'LANE 1 exists to give universities secure evidence of what students can do alone; supervised tasks protect the value of the degree and they reassure employers that graduates meet the standard', null, true, '2026-10-10 13:30+11', '2026-10-10 13:30+11'),
  ('60000000-0000-0000-0006-000000000001', '40000000-0000-0000-0000-000000000006', 1, E'Marking the process is harder than marking the product, but it asks a better question. My own log shows where I accepted advice and where I pushed back. A grader reading it can see my judgement at work, even if they never see the chat itself.', 'priya-shah-essay-2.docx', true, '2026-10-11 20:15+11', '2026-10-11 20:15+11'),
  ('60000000-0000-0000-0008-000000000001', '40000000-0000-0000-0000-000000000008', 1, E'This reflection looks at a time the AI was wrong with me. I asked whether a table can have two primary keys and it said yes. I checked the PostgreSQL documentation and found that a table has exactly one primary key, which can cover several columns. After that I stopped trusting short confident answers and started checking each one against a source.', null, true, '2026-10-11 18:30+11', '2026-10-11 18:30+11')
insert into public.analysis_results (id, project_id, final_version_id, iteration_id, analysis_version, model, rubric_version, ai_correctness_addressed, ai_correctness_evidence, verification_addressed, verification_evidence, changes_addressed, changes_evidence, explanation, uncertainty, created_at) values
  ('70000000-0000-0000-0002-000000000001', '40000000-0000-0000-0000-000000000002', '60000000-0000-0000-0002-000000000001', '50000000-0000-0000-0002-000000000001', 'analysis-v1', 'fixture-model', 'rubric-v1', true, 'Judged the workload point off-topic and kept the other points.', false, '', true, 'Dropped the workload point.', 'States what was kept and dropped, with a reason.', 'Low: the critique is brief but specific.', '2026-10-10 09:14+11'),
  ('70000000-0000-0000-0002-000000000002', '40000000-0000-0000-0000-000000000002', '60000000-0000-0000-0002-000000000001', '50000000-0000-0000-0002-000000000002', 'analysis-v1', 'fixture-model', 'rubric-v1', true, 'Said the Smith and Lee source does not exist.', true, 'Searched Google Scholar and the library.', true, 'Replaced it with the Sydney guidance.', 'Names the AI error, how it was checked and the replacement source.', 'Low: all three questions are answered directly.', '2026-10-10 09:14+11'),
  ('70000000-0000-0000-0002-000000000003', '40000000-0000-0000-0000-000000000002', '60000000-0000-0000-0002-000000000001', '50000000-0000-0000-0002-000000000003', 'analysis-v1', 'fixture-model', 'rubric-v1', true, 'Called the draft too generic.', false, '', true, 'Rewrote the introduction in their own words.', 'Gives a verdict and a change but no check.', 'Low: the change is visible in the final text.', '2026-10-10 09:14+11'),
  ('70000000-0000-0000-0002-000000000004', '40000000-0000-0000-0000-000000000002', '60000000-0000-0000-0002-000000000001', '50000000-0000-0000-0002-000000000004', 'analysis-v1', 'fixture-model', 'rubric-v1', true, 'Said the date was wrong.', true, 'Checked the Sydney article.', true, 'Fixed the date in the introduction.', 'Names the wrong date, the source used to check it and the fix.', 'Low: all three questions are answered directly.', '2026-10-10 09:14+11'),
  ('70000000-0000-0000-0002-000000000005', '40000000-0000-0000-0000-000000000002', '60000000-0000-0000-0002-000000000001', '50000000-0000-0000-0002-000000000005', 'analysis-v1', 'fixture-model', 'rubric-v1', true, 'Judged the paragraph clear.', true, 'Timed three logs at about ten minutes each.', false, '', 'Tests the claim about hours against their own timing.', 'Low: the check is specific.', '2026-10-10 09:14+11'),
  ('70000000-0000-0000-0002-000000000006', '40000000-0000-0000-0000-000000000002', '60000000-0000-0000-0002-000000000001', '50000000-0000-0000-0002-000000000006', 'analysis-v1', 'fixture-model', 'rubric-v1', false, '', false, '', false, '', 'The critique does not answer any of the three questions and skips the AI''s point about paragraph 4.', 'Moderate: a short critique may reflect a verbal discussion that is not logged.', '2026-10-10 09:14+11'),
  ('70000000-0000-0000-0002-000000000007', '40000000-0000-0000-0000-000000000002', '60000000-0000-0000-0002-000000000001', '50000000-0000-0000-0002-000000000007', 'analysis-v1', 'fixture-model', 'rubric-v1', true, 'Said the AI misquoted the survey.', true, 'Read Table 2 of the survey.', true, 'Corrected the figure to 71 percent.', 'Names the misquoted figure, the table used to check it and the correction.', 'Low: all three questions are answered directly.', '2026-10-10 09:14+11'),
  ('70000000-0000-0000-0002-000000000008', '40000000-0000-0000-0000-000000000002', '60000000-0000-0000-0002-000000000001', '50000000-0000-0000-0002-000000000008', 'analysis-v1', 'fixture-model', 'rubric-v1', false, '', false, '', true, 'Mentions revised wording without saying what changed.', 'Generic phrasing with no reference to specific wording, similar to AI-written summaries.', 'Moderate: tone alone is not proof of AI authorship.', '2026-10-10 09:14+11'),
  ('70000000-0000-0000-0002-000000000009', '40000000-0000-0000-0000-000000000002', '60000000-0000-0000-0002-000000000001', '50000000-0000-0000-0002-000000000009', 'analysis-v1', 'fixture-model', 'rubric-v1', true, 'Rejected the suggested conclusion rewrite.', false, '', true, 'Fixed two typos.', 'States one change made and one suggestion rejected.', 'Low: the critique is brief but specific.', '2026-10-10 09:14+11'),
